mapper.insert:
INSERT INTO collect_task (
    uuid, project_id, task_name, task_desc, executor_id, start_time, end_time,
    method_id, device_id, status, create_by, create_time, update_by, update_time, note, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{projectId}, #{taskName}, #{taskDesc}, #{executorId}, #{startTime}, #{endTime},
             #{methodId}, #{deviceId}, #{status}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{note}, #{isDel}
         )

mapper.select:
SELECT ct.* FROM collect_task ct LEFT JOIN project p ON ct.project_id = p.id WHERE ct.is_del = false
AND ct.task_name LIKE CONCAT('%', #{keyword}, '%')
AND p.uuid = CAST(#{projectUuid} AS uuid)
AND ct.status = #{status}
ORDER BY ct.start_time ASC LIMIT #{size} OFFSET #{offset}
